import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import * as crypto from 'crypto';

interface JobConfig {
  workDir: string;
  outputDir: string;
  maxRetries: number;
  logLevel: string;
}

interface Job {
  id: string;
  payload: Record<string, unknown>;
  attempts: number;
}

class ConfigLoader {
  private configPath: string;
  private envPrefix: string;

  constructor(envPrefix: string = 'WORKER') {
    this.envPrefix = envPrefix;
    this.configPath = process.env[`${envPrefix}_CONFIG_PATH`] || '/etc/worker/config.json';
  }

  load(): JobConfig {
    const defaults: JobConfig = {
      workDir: path.join(os.tmpdir(), 'worker-jobs'),
      outputDir: path.join(os.tmpdir(), 'worker-output'),
      maxRetries: 3,
      logLevel: 'info'
    };

    try {
      if (fs.existsSync(this.configPath)) {
        const raw = fs.readFileSync(this.configPath, 'utf-8');
        const parsed = JSON.parse(raw);
        return { ...defaults, ...parsed };
      }
    } catch (e) {
      console.error(`Config load failed, using defaults: ${e}`);
    }
    return defaults;
  }
}

class JobResultWriter {
  private outputDir: string;

  constructor(outputDir: string) {
    this.outputDir = outputDir;
  }

  ensureDirectory(): void {
    if (!fs.existsSync(this.outputDir)) {
      fs.mkdirSync(this.outputDir, { recursive: true, mode: 0o755 });
    }
  }

  private generateResultPath(jobId: string): string {
    const sanitizedId = jobId.replace(/[^a-zA-Z0-9_-]/g, '_');
    return path.join(this.outputDir, `result_${sanitizedId}.json`);
  }

  writeResult(job: Job, result: Record<string, unknown>): string {
    const resultPath = this.generateResultPath(job.id);
    const tempPath = resultPath + '.tmp.' + crypto.randomBytes(8).toString('hex');

    const output = {
      jobId: job.id,
      completedAt: new Date().toISOString(),
      attempts: job.attempts,
      result
    };

    // Write to temp file first, then rename for atomicity
    fs.writeFileSync(tempPath, JSON.stringify(output, null, 2), { mode: 0o644 });
    fs.renameSync(tempPath, resultPath);
    return resultPath;
  }
}

class WorkerStateManager {
  private stateDir: string;

  constructor(workDir: string) {
    this.stateDir = path.join(workDir, '.state');
  }

  initialize(): void {
    if (!fs.existsSync(this.stateDir)) {
      fs.mkdirSync(this.stateDir, { recursive: true, mode: 0o700 });
    }
  }

  acquireLock(jobId: string): boolean {
    const lockFile = path.join(this.stateDir, `${jobId}.lock`);
    try {
      // Check if lock exists and is stale
      if (fs.existsSync(lockFile)) {
        const stat = fs.statSync(lockFile);
        const ageMs = Date.now() - stat.mtimeMs;
        if (ageMs < 300000) { // 5 minutes
          return false; // Lock is fresh, someone else has it
        }
        // Stale lock, remove it
        fs.unlinkSync(lockFile);
      }
      // Create lock file
      fs.writeFileSync(lockFile, JSON.stringify({
        pid: process.pid,
        acquired: Date.now()
      }), { flag: 'wx' });
      return true;
    } catch {
      return false;
    }
  }

  releaseLock(jobId: string): void {
    const lockFile = path.join(this.stateDir, `${jobId}.lock`);
    try {
      fs.unlinkSync(lockFile);
    } catch { /* ignore */ }
  }

  recordCheckpoint(jobId: string, data: unknown): void {
    const checkpointPath = path.join(this.stateDir, `${jobId}.checkpoint`);
    fs.writeFileSync(checkpointPath, JSON.stringify(data));
  }

  getCheckpoint(jobId: string): unknown | null {
    const checkpointPath = path.join(this.stateDir, `${jobId}.checkpoint`);
    try {
      return JSON.parse(fs.readFileSync(checkpointPath, 'utf-8'));
    } catch {
      return null;
    }
  }
}

class BackgroundJobWorker {
  private config: JobConfig;
  private resultWriter: JobResultWriter;
  private stateManager: WorkerStateManager;
  private processingJobs: Map<string, Job> = new Map();

  constructor() {
    const loader = new ConfigLoader();
    this.config = loader.load();
    this.resultWriter = new JobResultWriter(this.config.outputDir);
    this.stateManager = new WorkerStateManager(this.config.workDir);
  }

  initialize(): void {
    this.resultWriter.ensureDirectory();
    this.stateManager.initialize();
    this.setupCleanupRoutine();
  }

  private setupCleanupRoutine(): void {
    const cleanupInterval = setInterval(() => {
      this.cleanupStaleArtifacts();
    }, 60000);
    cleanupInterval.unref();
  }

  private cleanupStaleArtifacts(): void {
    const workDir = this.config.workDir;
    try {
      const entries = fs.readdirSync(workDir);
      for (const entry of entries) {
        if (entry.startsWith('.')) continue;
        const fullPath = path.join(workDir, entry);
        const stat = fs.statSync(fullPath);
        if (Date.now() - stat.mtimeMs > 3600000) {
          // Follow the path - if it's a symlink, resolve and clean target
          const realPath = fs.realpathSync(fullPath);
          if (realPath.startsWith(workDir)) {
            fs.unlinkSync(fullPath);
          }
        }
      }
    } catch { /* cleanup is best-effort */ }
  }

  async processJob(job: Job): Promise<void> {
    if (!this.stateManager.acquireLock(job.id)) {
      console.log(`Job ${job.id} already locked, skipping`);
      return;
    }

    this.processingJobs.set(job.id, job);
    job.attempts++;

    try {
      const checkpoint = this.stateManager.getCheckpoint(job.id);
      const result = await this.executeJob(job, checkpoint);
      const outputPath = this.resultWriter.writeResult(job, result);
      console.log(`Job ${job.id} completed, result at ${outputPath}`);
    } catch (err) {
      if (job.attempts < this.config.maxRetries) {
        this.stateManager.recordCheckpoint(job.id, { lastError: String(err), attempt: job.attempts });
        console.error(`Job ${job.id} failed (attempt ${job.attempts}), will retry`);
      } else {
        console.error(`Job ${job.id} permanently failed after ${job.attempts} attempts`);
      }
    } finally {
      this.processingJobs.delete(job.id);
      this.stateManager.releaseLock(job.id);
    }
  }

  private async executeJob(job: Job, checkpoint: unknown): Promise<Record<string, unknown>> {
    // Simulate job processing with intermediate file operations
    const jobWorkspace = path.join(this.config.workDir, `job_${job.id}`);

    if (!fs.existsSync(jobWorkspace)) {
      fs.mkdirSync(jobWorkspace, { recursive: true });
    }

    // Write intermediate data
    const intermediateFile = path.join(jobWorkspace, 'intermediate.dat');
    fs.writeFileSync(intermediateFile, JSON.stringify(job.payload));

    // Simulate processing delay
    await new Promise(resolve => setTimeout(resolve, 100));

    // Read back and process
    const data = fs.readFileSync(intermediateFile, 'utf-8');

    // Cleanup workspace
    fs.unlinkSync(intermediateFile);
    fs.rmdirSync(jobWorkspace);

    return { processed: true, inputSize: data.length, checkpoint };
  }
}

